const cfg = $('Validar Configuração Segura').first().json;
const zone = cfg.timezone || 'America/Sao_Paulo';
const end = $now.setZone(zone);
const start = end.minus({ hours: Number(cfg.lookbackHours || 24) });
const generatedDate = end.toFormat('yyyy-MM-dd');
return [{ json: {
  ...cfg,
  discoveredFrom: start.toUTC().toISO(),
  discoveredTo: end.toUTC().toISO(),
  publishedFrom: start.toUTC().toISO(),
  publishedTo: end.toUTC().toISO(),
  periodLabel: start.toFormat('dd/MM/yyyy HH:mm') + ' BRT → ' + end.toFormat('dd/MM/yyyy HH:mm') + ' BRT',
  generatedAt: generatedDate,
  generatedAtLabel: end.toFormat('dd/MM/yyyy HH:mm:ss') + ' BRT',
  windowMode: 'rolling_window',
  windowHours: Number(cfg.lookbackHours || 24),
  reportId: cfg.runId,
  filename: 'relatorio_cti_' + generatedDate + '_' + cfg.runId + '.txt',
  pdfFileName: 'relatorio_cti_' + generatedDate + '_' + cfg.runId + '.pdf',
  htmlFileName: 'relatorio_cti_' + generatedDate + '_' + cfg.runId + '.html',
} }];

const win = $('Calcular Janela').first().json;
const ransRaw = $('GET Ransomware').first().json;
const kevRaw = $('GET CISA KEV').first().json;
const cveRaw = $('GET CVEs NVD').first().json;
const sevC = Number(($('GET CVE Sev Critical').first().json || {}).total ?? NaN);
const sevH = Number(($('GET CVE Sev High').first().json || {}).total ?? NaN);
const sevM = Number(($('GET CVE Sev Medium').first().json || {}).total ?? NaN);
const sevL = Number(($('GET CVE Sev Low').first().json || {}).total ?? NaN);
const companiesRaw = $('Clientes NGSOC').first().json;

const victims = Array.isArray(ransRaw?.items) ? ransRaw.items : (Array.isArray(ransRaw) ? ransRaw : []);
const kevEntries = Array.isArray(kevRaw?.items) ? kevRaw.items : (Array.isArray(kevRaw) ? kevRaw : []);
const cveItems = Array.isArray(cveRaw?.items) ? cveRaw.items : (Array.isArray(cveRaw) ? cveRaw : []);
const companies = Array.isArray(companiesRaw?.companies) ? companiesRaw.companies : [];

const ngsoc = companies.filter(c => String(c.name || '').includes('(NGSOC)'));
const ngsocNames = ngsoc.map(c => String(c.name || '').replace(/\s*\(NGSOC\)\s*/i, '').trim().toLowerCase());

function norm(s) { return String(s || '').toLowerCase().trim(); }
function countBy(arr, keyFn) {
  const m = {};
  for (const x of arr) {
    const k = keyFn(x) || 'N/A';
    m[k] = (m[k] || 0) + 1;
  }
  return Object.entries(m).sort((a, b) => b[1] - a[1]);
}
function topLines(entries, n = 12) {
  return entries.slice(0, n).map(([k, v]) => '- ' + k + ': ' + v).join('\n') || '- (sem dados)';
}
function dayKey(iso) {
  if (!iso) return 'N/A';
  try {
    return DateTime.fromISO(String(iso), { zone: 'utc' }).setZone('America/Sao_Paulo').toFormat('dd/MM');
  } catch (e) {
    return String(iso).slice(0, 10);
  }
}
function titleCaseGroup(g) {
  const s = String(g || 'N/A');
  if (s === 'N/A') return s;
  return s.charAt(0).toUpperCase() + s.slice(1);
}

const byDay = countBy(victims, v => dayKey(v.discovered || v.discoveredAt || v.discovered_at));
const byGroup = countBy(victims, v => titleCaseGroup(v.group || v.groupName || 'N/A'));
const byCountry = countBy(victims, v => v.country || v.countryCode || 'N/A');
const bySector = countBy(victims, v => v.sector || (Array.isArray(v.sectorKeys) ? v.sectorKeys.join(',') : '') || 'N/A');

const brVictims = victims.filter(v => String(v.country || v.countryCode || '').toUpperCase() === 'BR');
const brLines = brVictims.map(v =>
  '- ' + (v.victim || v.name || 'N/A') + ' | ' + (v.group || 'N/A') + ' | ' + (v.sector || 'N/A') + ' | ' + dayKey(v.discovered || v.discoveredAt)
).join('\n') || '- Nenhuma no período';

const nominalHits = victims.filter(v => {
  const name = norm(v.victim || v.name);
  return Boolean(name) && ngsocNames.some(n => n && (name.includes(n) || n.includes(name)));
});

const fromIso = DateTime.fromISO(win.discoveredFrom);
const toIso = DateTime.fromISO(win.discoveredTo);
const kevInWindow = kevEntries.filter(e => {
  const d = e.dateAdded || e.date_added || e.added;
  if (!d) return false;
  const dt = DateTime.fromISO(String(d));
  return dt >= fromIso && dt <= toIso;
});
const kevLines = kevInWindow.slice(0, 20).map(e => {
  const cve = e.cveId || e.cveID || e.cve || 'N/A';
  const prod = [e.vendorProject, e.product].filter(Boolean).join(' ') || e.product || e.vendor || 'N/A';
  const vuln = e.vulnerabilityName || e.shortDescription || e.description || '';
  const rw = e.knownRansomwareUse || e.knownRansomwareCampaignUse || e.ransomwareUse || 'Unknown';
  return '- ' + cve + ' | ' + prod + ' | ' + String(vuln).trim().slice(0, 140) + ' | Uso por ransomware: ' + rw;
}).join('\n') || '- Nenhuma adição KEV na janela';

function sevOf(c) {
  return String(
    c.cvss_v3_severity || c.cvssV3Severity || c.severity || c.cvssSeverity || ''
  ).toUpperCase();
}
function cveIdOf(c) { return c.cve_id || c.cveId || c.id || 'N/A'; }
function cveScoreOf(c) {
  const s = c.cvss_v3_score ?? c.cvssV3Score ?? c.cvss ?? '';
  return s === null || s === undefined ? '' : s;
}
function cveDescOf(c) { return String(c.description || c.summary || ''); }

const sevFromPage = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0, NONE: 0 };
for (const c of cveItems) {
  const s = sevOf(c);
  if (s === 'CRITICAL') sevFromPage.CRITICAL++;
  else if (s === 'HIGH') sevFromPage.HIGH++;
  else if (s === 'MEDIUM') sevFromPage.MEDIUM++;
  else if (s === 'LOW') sevFromPage.LOW++;
  else sevFromPage.NONE++;
}

const sev = {
  CRITICAL: Number.isFinite(sevC) ? sevC : sevFromPage.CRITICAL,
  HIGH: Number.isFinite(sevH) ? sevH : sevFromPage.HIGH,
  MEDIUM: Number.isFinite(sevM) ? sevM : sevFromPage.MEDIUM,
  LOW: Number.isFinite(sevL) ? sevL : sevFromPage.LOW,
  NONE: 0,
};
const cveTotal = Number(cveRaw?.total ?? cveItems.length);
const accounted = sev.CRITICAL + sev.HIGH + sev.MEDIUM + sev.LOW;
sev.NONE = Math.max(0, cveTotal - accounted);

const critRaw = $('GET CVE Sev Critical').first().json;
const critPool = Array.isArray(critRaw?.items) ? critRaw.items : [];
const criticals = (critPool.length ? critPool : cveItems.filter(c => sevOf(c) === 'CRITICAL'))
  .sort((a, b) => Number(cveScoreOf(b) || 0) - Number(cveScoreOf(a) || 0))
  .slice(0, 12);
const critLines = criticals.map(c => {
  const id = cveIdOf(c);
  const score = cveScoreOf(c);
  const desc = cveDescOf(c).slice(0, 110);
  return '- ' + id + (score !== '' ? ' | ' + score : '') + ' | ' + desc;
}).join('\n') || '- Nenhum Critical na página';

const highs = cveItems.filter(c => sevOf(c) === 'HIGH').slice(0, 40);
const themes = [];
const blob = (criticals.concat(highs).map(c => cveDescOf(c) + ' ' + cveIdOf(c))).join(' ').toLowerCase();
if (/rce|remote code|takeover|arbitrary code/.test(blob)) themes.push('Takeover / RCE');
if (/auth(entication)? bypass|improper authentication/.test(blob)) themes.push('Authentication bypass');
if (/sql injection|sqli/.test(blob)) themes.push('SQL Injection');
if (/path traversal|dot-dot|directory traversal/.test(blob)) themes.push('Path traversal / bypass de filtros');
if (/privilege|eleva/.test(blob)) themes.push('Elevação de privilégios');
if (!themes.length) themes.push('Diversos (ver destaques Critical/High)');

const SEGMENT_MAP = [
  { keys: ['healthcare', 'health', 'pharma', 'farmac'], label: 'Saúde/Farmacêutico', clients: ['Unimed Vale Rio dos Sinos', 'Hertzfarma'] },
  { keys: ['manufactur', 'industrial', 'industr'], label: 'Indústria', clients: ['Fitesa', 'Hertzfarma', 'Killing', 'Taurus Armas', 'Vipal', 'Fruki'] },
  { keys: ['retail', 'e-commerce', 'ecommerce'], label: 'Varejo', clients: ['Piccadilly'] },
  { keys: ['transport', 'logistics', 'freight'], label: 'Transporte e Logística', clients: ['Cargolift'] },
  { keys: ['real estate', 'propert', 'imobil'], label: 'Imobiliário', clients: ['Auxiliadora Predial'] },
  { keys: ['agricult', 'food', 'alimento'], label: 'Alimentos/Agronegócio', clients: ['Santa Clara', 'SLC Agrícola', 'Fruki'] },
];

const correlatos = [];
for (const seg of SEGMENT_MAP) {
  const hit = victims.some(v => {
    const s = norm(v.sector) + ' ' + (Array.isArray(v.sectorKeys) ? v.sectorKeys.join(' ') : '');
    return seg.keys.some(k => s.includes(k));
  });
  if (hit) correlatos.push(seg.label + ' (' + seg.clients.join(', ') + ')');
}

const aberturaFatos = [];
if (nominalHits.length === 0) {
  aberturaFatos.push('nenhum cliente NGSOC aparece como vítima nominal nas divulgações de ransomware (cruzamento com a base Recon5)');
} else {
  aberturaFatos.push('possível match nominal NGSOC: ' + nominalHits.map(v => v.victim || v.name).join(', '));
}
if (correlatos.length) {
  aberturaFatos.push('houve ' + victims.length + ' novas vítimas em leak sites, com atividade em setores correlatos a segmentos NGSOC — ' + correlatos.join(', ') + ' —');
} else if (bySector.length) {
  aberturaFatos.push('houve ' + victims.length + ' novas vítimas em leak sites, com atividade em setores observados (' + bySector.slice(0, 5).map(([s]) => s).join(', ') + ')');
} else {
  aberturaFatos.push('houve ' + victims.length + ' novas vítimas em leak sites');
}
if (brVictims.length) {
  aberturaFatos.push('incluindo no Brasil ' + brVictims.map(v => (v.victim || v.name) + ' (' + titleCaseGroup(v.group || 'N/A') + ')').join(', '));
}
if (kevInWindow.length) {
  const kevHint = kevInWindow.slice(0, 2).map(e => {
    const prod = [e.vendorProject, e.product].filter(Boolean).join(' ') || e.product || 'N/A';
    return prod;
  }).join(' e ');
  aberturaFatos.push('No CISA KEV, ' + kevInWindow.length + ' nova(s) entrada(s) (' + kevHint + ')');
} else {
  aberturaFatos.push('No CISA KEV, sem novas entradas na janela');
}

const report = [
  'Relatório CTI — Diário (' + win.periodLabel + ')',
  'Fonte: Recon5 (ransomware.live / CISA KEV / catálogo NVD de CVEs)',
  'Gerado em: ' + win.generatedAt,
  'Período: últimas 24 horas → momento da geração',
  '',
  '================================================================================',
  'ABERTURA',
  '================================================================================',
  '',
  'Bom dia, pessoal!',
  '',
  'Nas últimas 24 horas, ' + aberturaFatos.join('. ').replace(/\s+\./g, '.') + '.',
  '',
  'O monitoramento contemplou a análise de possíveis vazamentos de dados, menções aos clientes e aos seus setores, vulnerabilidades críticas (CVEs) com exploração ativa, novas vítimas divulgadas por grupos de ransomware, bem como campanhas maliciosas e demais ameaças relevantes ao cenário de segurança cibernética.',
  '',
  'Seguimos com o monitoramento contínuo e informaremos prontamente caso sejam identificados eventos que demandem atenção.',
  '',
  '================================================================================',
  '1. RANSOMWARE (vítimas em leak sites)',
  '================================================================================',
  '',
  'Na janela diária, a inteligência de ameaças do Recon5 registrou ' + victims.length + ' novas vítimas de ransomware em leak sites.',
  '',
  'Volume por dia (discovered):',
  topLines(byDay, 14),
  '',
  'Grupos mais ativos:',
  topLines(byGroup, 12),
  '',
  'Países:',
  topLines(byCountry, 20),
  '',
  'Setores:',
  topLines(bySector, 15),
  '',
  'Vítimas no Brasil:',
  brLines,
  '',
  '================================================================================',
  '2. CISA KEV (Known Exploited Vulnerabilities)',
  '================================================================================',
  '',
  kevInWindow.length
    ? ('Foram adicionadas ' + kevInWindow.length + ' vulnerabilidades ao catálogo CISA KEV na janela:')
    : 'Não houve adições ao catálogo CISA KEV na janela.',
  '',
  kevLines,
  '',
  '================================================================================',
  '3. CATÁLOGO DE CVEs (NVD)',
  '================================================================================',
  '',
  'No catálogo NVD foram publicadas ' + cveTotal + ' vulnerabilidades na janela, com a seguinte distribuição de severidade CVSSv3:',
  '',
  '- Critical: ' + sev.CRITICAL,
  '- High: ' + sev.HIGH,
  '- Medium: ' + sev.MEDIUM,
  '- Low: ' + sev.LOW,
  '- Sem severidade atribuída (ainda): ' + sev.NONE,
  '',
  'Temas predominantes (amostra Critical + High):',
  themes.map(t => '- ' + t).join('\n'),
  '',
  'Destaques Critical:',
  critLines,
].join('\n');

return [{
  json: {
    reportText: report,
    periodLabel: win.periodLabel,
    generatedAt: win.generatedAt,
    generatedAtLabel: win.generatedAtLabel,
    filename: win.filename,
    pdfFileName: win.pdfFileName,
    htmlFileName: win.htmlFileName,
    reportId: win.reportId,
    reportVersion: win.reportVersion,
    classification: win.classification,
    organization: win.organization,
    stats: {
      ransomwareVictims: victims.length,
      brVictims: brVictims.length,
      ngsocNominalHits: nominalHits.length,
      kevAdded: kevInWindow.length,
      cveTotal,
      cveSeverity: sev,
      correlatos,
      byGroup: byGroup.slice(0, 8),
      byCountry: byCountry.slice(0, 8),
      bySector: bySector.slice(0, 8),
      byDay,
      brLines: brVictims.map(v => ({
        victim: v.victim || v.name,
        group: v.group,
        sector: v.sector,
        day: dayKey(v.discovered),
      })),
      kevLines: kevInWindow.slice(0, 10).map(e => ({
        cve: e.cveId || e.cveID,
        product: [e.vendorProject, e.product].filter(Boolean).join(' '),
        name: e.vulnerabilityName || e.shortDescription,
        rw: e.knownRansomwareUse || 'Unknown',
      })),
      criticals: criticals.map(c => ({
        id: cveIdOf(c),
        score: cveScoreOf(c),
        desc: cveDescOf(c).slice(0, 140),
      })),
      themes,
      abertura: 'Nas últimas 24 horas, ' + aberturaFatos.join('. ').replace(/\s+\./g, '.') + '.',
    },
  },
}];

const src = $input.first().json;
const stats = src.stats || {};
const sev = stats.cveSeverity || {};
const periodLabel = String(src.periodLabel || '');
const generatedAtLabel = String(src.generatedAtLabel || src.generatedAt || '');
const pdfFileName = String(src.pdfFileName || ('relatorio_cti_' + (src.generatedAt || 'hoje') + '.pdf'));

const C = {
  header: [0.498, 0.11, 0.098],      // #7F1D1D
  headerAccent: [0.725, 0.11, 0.11], // #B91C1C
  text: [0.059, 0.09, 0.165],        // #0F172A
  muted: [0.278, 0.333, 0.412],      // #475569
  soft: [0.392, 0.455, 0.545],       // #64748B
  card: [1, 1, 1],
  bg: [0.965, 0.973, 0.98],
  line: [0.898, 0.906, 0.922],
  critBg: [0.996, 0.886, 0.886],
  crit: [0.725, 0.11, 0.11],
  high: [0.498, 0.11, 0.098],
  med: [0.961, 0.62, 0.043],
  low: [0.008, 0.525, 0.78],
  white: [1, 1, 1],
};

function toWinAnsiBytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c === 10 || c === 13) { out.push(c); continue; }
    if (c === 0x2192 || c === 0x2014) { // → —
      out.push(c === 0x2192 ? 0x3E : 0x2D); // > or -
      if (c === 0x2192) { out.push(0x20); } // space after >
      continue;
    }
    if (c < 128) { out.push(c); continue; }
    const map = {
      0x20AC: 0x80, 0x201A: 0x82, 0x0192: 0x83, 0x201E: 0x84, 0x2026: 0x85,
      0x2020: 0x86, 0x2021: 0x87, 0x02C6: 0x88, 0x2030: 0x89, 0x0160: 0x8A,
      0x2039: 0x8B, 0x0152: 0x8C, 0x017D: 0x8E, 0x2018: 0x91, 0x2019: 0x92,
      0x201C: 0x93, 0x201D: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
      0x02DC: 0x98, 0x2122: 0x99, 0x0161: 0x9A, 0x203A: 0x9B, 0x0153: 0x9C,
      0x017E: 0x9E, 0x0178: 0x9F,
    };
    if (map[c] != null) out.push(map[c]);
    else if (c >= 0xA0 && c <= 0xFF) out.push(c);
    else out.push(0x3F);
  }
  return out;
}

function pdfEscape(str) {
  const bytes = toWinAnsiBytes(String(str));
  let s = '';
  for (const b of bytes) {
    if (b === 0x28 || b === 0x29 || b === 0x5C) s += '\\' + String.fromCharCode(b);
    else if (b < 32 || b > 126) s += '\\' + b.toString(8).padStart(3, '0');
    else s += String.fromCharCode(b);
  }
  return s;
}

function wrap(text, maxChars) {
  const raw = String(text || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const out = [];
  for (const paragraph of raw.split('\n')) {
    if (!paragraph) { out.push(''); continue; }
    let rest = paragraph;
    while (rest.length > maxChars) {
      let cut = rest.lastIndexOf(' ', maxChars);
      if (cut < Math.floor(maxChars * 0.45)) cut = maxChars;
      out.push(rest.slice(0, cut));
      rest = rest.slice(cut).replace(/^\s+/, '');
    }
    if (rest) out.push(rest);
  }
  return out;
}

function rgb(arr) { return arr.map(x => Number(x).toFixed(3)).join(' ') + ' rg'; }
function RG(arr) { return arr.map(x => Number(x).toFixed(3)).join(' ') + ' RG'; }

function rect(x, y, w, h, fill, stroke) {
  let s = '';
  if (fill) s += rgb(fill) + '\n';
  if (stroke) s += RG(stroke) + '\n0.6 w\n';
  s += x + ' ' + y + ' ' + w + ' ' + h + ' re\n';
  if (fill && stroke) s += 'B\n';
  else if (fill) s += 'f\n';
  else s += 'S\n';
  return s;
}

function textAt(x, y, str, font, size) {
  return 'BT /' + font + ' ' + size + ' Tf ' + x + ' ' + y + ' Td (' + pdfEscape(str) + ') Tj ET\n';
}

const pageW = 595;
const pageH = 842;
const margin = 36;
const contentW = pageW - margin * 2;

const pagesContent = [];
let ops = '';
let y = pageH - 36;

function newPage() {
  if (ops) pagesContent.push(ops);
  ops = '';
  // background
  ops += rect(0, 0, pageW, pageH, C.bg, null);
  y = pageH - 36;
}

function ensure(space) {
  if (y - space < 52) {
    drawFooter();
    newPage();
    drawMiniHeader();
  }
}

function drawFooter() {
  ops += rect(0, 0, pageW, 34, [0.933, 0.945, 0.957], null);
  ops += textAt(margin, 14, 'Gerado em ' + generatedAtLabel + '  •  Recon5  •  Classificação: Confidencial  •  recon5@netfive.com.br', 'F1', 8);
}

function drawMiniHeader() {
  ops += rect(0, pageH - 28, pageW, 28, C.header, null);
  ops += rgb(C.white) + '\n';
  ops += textAt(margin, pageH - 18, 'Relatório CTI Diário — Netfive / Recon5', 'F2', 9);
  y = pageH - 48;
}

function drawMainHeader() {
  ops += rect(0, pageH - 92, pageW, 92, C.header, null);
  // title pill
  ops += rect(margin, pageH - 58, 250, 28, C.white, null);
  ops += rgb(C.text) + '\n';
  ops += textAt(margin + 10, pageH - 48, 'Relatório CTI Diário', 'F2', 14);
  // period pill
  const pill = 'Período: ' + periodLabel.replace(/→/g, '>').slice(0, 52);
  ops += rect(pageW - margin - 250, pageH - 54, 250, 22, C.white, null);
  ops += rgb(C.header) + '\n';
  ops += textAt(pageW - margin - 240, pageH - 46, pill, 'F2', 8);
  ops += rgb(C.white) + '\n';
  ops += textAt(margin, pageH - 78, 'Fonte: Recon5 (ransomware.live / CISA KEV / NVD)', 'F1', 9);
  y = pageH - 112;
}

function sectionTitle(title) {
  ensure(28);
  ops += rgb(C.soft) + '\n';
  ops += textAt(margin, y, String(title).toUpperCase(), 'F2', 10);
  y -= 6;
  ops += rect(margin, y, contentW, 1.2, C.line, null);
  y -= 16;
}

function bodyText(text, size = 9, color = C.muted, max = 98) {
  const lines = wrap(text, max);
  for (const line of lines) {
    ensure(14);
    ops += rgb(color) + '\n';
    ops += textAt(margin, y, line, 'F1', size);
    y -= 12;
  }
}

function bullet(text) {
  const lines = wrap(text, 94);
  for (let i = 0; i < lines.length; i++) {
    ensure(14);
    ops += rgb(C.muted) + '\n';
    ops += textAt(margin + (i === 0 ? 0 : 10), y, (i === 0 ? '• ' : '  ') + lines[i], 'F1', 9);
    y -= 12;
  }
}

function metricCards() {
  ensure(78);
  const cards = [
    { label: 'VÍTIMAS RANSOMWARE', value: String(stats.ransomwareVictims ?? 0), color: C.headerAccent },
    { label: 'VÍTIMAS BR', value: String(stats.brVictims ?? 0), color: C.crit },
    { label: 'KEV NOVAS', value: String(stats.kevAdded ?? 0), color: C.med },
    { label: 'CVEs NVD', value: String(stats.cveTotal ?? 0), color: C.low },
  ];
  const gap = 10;
  const w = (contentW - gap * 3) / 4;
  const h = 62;
  const baseY = y - h;
  cards.forEach((c, i) => {
    const x = margin + i * (w + gap);
    ops += rect(x, baseY, w, h, C.card, C.line);
    ops += rgb(C.soft) + '\n';
    ops += textAt(x + 8, baseY + 46, c.label, 'F2', 7);
    ops += rgb(c.color) + '\n';
    ops += textAt(x + 8, baseY + 18, c.value, 'F2', 18);
  });
  y = baseY - 18;
}

function severityCard() {
  ensure(110);
  const boxH = 100;
  const boxY = y - boxH;
  ops += rect(margin, boxY, contentW, boxH, C.card, C.line);
  ops += rgb(C.soft) + '\n';
  ops += textAt(margin + 12, boxY + boxH - 16, 'CVEs POR SEVERIDADE (CVSSv3)', 'F2', 9);

  const rows = [
    { label: 'Crítico', q: sev.CRITICAL || 0, tag: C.critBg, tc: C.crit, bar: C.crit },
    { label: 'Alto', q: sev.HIGH || 0, tag: C.header, tc: C.white, bar: C.header },
    { label: 'Médio', q: sev.MEDIUM || 0, tag: [0.996, 0.953, 0.78], tc: [0.573, 0.251, 0.055], bar: C.med },
    { label: 'Baixo', q: sev.LOW || 0, tag: [0.859, 0.918, 0.996], tc: C.low, bar: C.low },
  ];
  const maxQ = Math.max(1, ...rows.map(r => r.q));
  rows.forEach((r, i) => {
    const ry = boxY + boxH - 34 - i * 16;
    ops += rect(margin + 12, ry - 2, 52, 12, r.tag, null);
    ops += rgb(r.tc) + '\n';
    ops += textAt(margin + 16, ry + 1, r.label, 'F2', 8);
    ops += rgb(C.text) + '\n';
    ops += textAt(margin + 72, ry + 1, String(r.q), 'F2', 9);
    const bw = Math.max(4, Math.round((contentW - 140) * (r.q / maxQ)));
    ops += rect(margin + 100, ry, bw, 8, r.bar, null);
  });
  y = boxY - 16;
}

