// Assemble PDF
const objects = [];
const addObj = (body) => { objects.push(body); return objects.length; };
const fontId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
const fontBoldId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');

const contentIds = [];
const pageIds = [];
for (let p = 0; p < pagesContent.length; p++) {
  let stream = pagesContent[p];
  stream = stream.replace(/\/F1 /g, '/' + 'F1' + ' ').replace(/\/F2 /g, '/' + 'F2' + ' ');
  // fonts aliases F1/F2 in content already; Resources maps F1/F2
  const contentId = addObj('<< /Length ' + Buffer.byteLength(stream, 'latin1') + ' >>\nstream\n' + stream + '\nendstream');
  contentIds.push(contentId);
  pageIds.push(null);
}

const kids = [];
for (let p = 0; p < pagesContent.length; p++) {
  const pageId = addObj(
    '<< /Type /Page /Parent PAGES_ID 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ' +
      fontId + ' 0 R /F2 ' + fontBoldId + ' 0 R >> >> /Contents ' + contentIds[p] + ' 0 R >>'
  );
  pageIds[p] = pageId;
  kids.push(pageId + ' 0 R');
}
const pagesId = addObj('<< /Type /Pages /Kids [' + kids.join(' ') + '] /Count ' + pagesContent.length + ' >>');
for (let i = 0; i < objects.length; i++) objects[i] = objects[i].replace(/PAGES_ID/g, String(pagesId));
const catalogId = addObj('<< /Type /Catalog /Pages ' + pagesId + ' 0 R >>');

let pdf = '%PDF-1.4\n';
const offsets = [0];
for (let i = 0; i < objects.length; i++) {
  offsets.push(Buffer.byteLength(pdf, 'latin1'));
  pdf += (i + 1) + ' 0 obj\n' + objects[i] + '\nendobj\n';
}
const xrefPos = Buffer.byteLength(pdf, 'latin1');
pdf += 'xref\n0 ' + (objects.length + 1) + '\n';
pdf += '0000000000 65535 f \n';
for (let i = 1; i <= objects.length; i++) {
  pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
}
pdf += 'trailer\n<< /Size ' + (objects.length + 1) + ' /Root ' + catalogId + ' 0 R >>\n';
pdf += 'startxref\n' + xrefPos + '\n%%EOF';

const pdfBase64 = Buffer.from(pdf, 'latin1').toString('base64');

return [{
  json: {
    ...src,
    pdfFileName,
    pdfBase64,
    pdfPages: pagesContent.length,
  },
}];

const cfg = $input.first().json;
const required = ['baseUrl', 'username', 'recon5Password', 'tenantId'];
const missing = required.filter(k => cfg[k] === undefined || cfg[k] === null || String(cfg[k]).trim() === '');
if (missing.length) {
  throw new Error('Configuração CTI incompleta. Variáveis ausentes: ' + missing.join(', ') +
    '. Configure-as no ambiente do n8n; nenhum segredo deve ser salvo no workflow.');
}
let parsed;
try { parsed = new URL(String(cfg.baseUrl)); } catch {
  throw new Error('RECON5_BASE_URL não é uma URL válida.');
}
if (parsed.protocol !== 'https:') throw new Error('RECON5_BASE_URL deve usar HTTPS.');
const cleanBaseUrl = String(cfg.baseUrl).replace(/\/+$/, '');
const lookbackHours = Math.min(168, Math.max(1, Number(cfg.lookbackHours || 24)));
const runId = 'cti-' + $now.toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'") + '-' +
  Math.random().toString(36).slice(2, 8);
return [{ json: {
  ...cfg,
  baseUrl: cleanBaseUrl,
  lookbackHours,
  ransomwareLimit: Math.min(1000, Math.max(1, Number(cfg.ransomwareLimit || 500))),
  cveLimit: Math.min(1000, Math.max(1, Number(cfg.cveLimit || 500))),
  runId,
  configValidatedAt: $now.toUTC().toISO(),
} }];

const src = $input.first().json;
const stats = src.stats || {};
const sev = stats.cveSeverity || {};
const qualityIssues = [];
if (!src.periodLabel) qualityIssues.push('Período de análise ausente');
if (!Number.isFinite(Number(stats.cveTotal))) qualityIssues.push('Total de CVEs inválido');
if (!Array.isArray(stats.byGroup)) qualityIssues.push('Agregação de grupos indisponível');
if (!Array.isArray(stats.byCountry)) qualityIssues.push('Agregação de países indisponível');
if ((stats.ransomwareVictims || 0) >= 500) qualityIssues.push('Ransomware atingiu o limite da consulta; revisar paginação');
if ((stats.cveTotal || 0) >= 500) qualityIssues.push('CVEs podem exceder a página consultada; revisar paginação');

let score = 0;
score += Math.min(30, Number(sev.CRITICAL || 0) * 3);
score += Math.min(18, Number(sev.HIGH || 0) * 0.4);
score += Math.min(25, Number(stats.kevAdded || 0) * 8);
score += Math.min(15, Number(stats.brVictims || 0) * 5);
score += Math.min(12, Number(stats.ransomwareVictims || 0) * 0.3);
if (Number(stats.ngsocNominalHits || 0) > 0) score = Math.max(score, 90);
score = Math.min(100, Math.round(score));

const level = score >= 80 ? 'CRÍTICO' : score >= 60 ? 'ALTO' : score >= 35 ? 'MODERADO' : 'BAIXO';
const confidence = qualityIssues.length === 0 ? 'ALTA' : qualityIssues.length <= 2 ? 'MÉDIA' : 'BAIXA';
const recommendations = [];
if (Number(stats.ngsocNominalHits || 0) > 0)
  recommendations.push({priority:'P0', action:'Validar imediatamente o possível match nominal com o cliente e acionar o playbook de incidente.', owner:'SOC/CSIRT'});
if (Number(stats.kevAdded || 0) > 0)
  recommendations.push({priority:'P1', action:'Cruzar os novos itens CISA KEV com inventário, exposição externa e telemetria EDR/SIEM.', owner:'Vulnerability Management'});
if (Number(sev.CRITICAL || 0) > 0)
  recommendations.push({priority:'P1', action:'Priorizar CVEs críticas por exposição, exploitabilidade, criticidade do ativo e controles compensatórios.', owner:'SecOps/Infra'});
if (Number(stats.brVictims || 0) > 0)
  recommendations.push({priority:'P2', action:'Reforçar hunting para TTPs dos grupos ativos no Brasil e revisar terceiros do mesmo setor.', owner:'Threat Hunting'});
if ((stats.correlatos || []).length)
  recommendations.push({priority:'P2', action:'Notificar analistas responsáveis pelos segmentos correlatos e ampliar monitoramento contextual.', owner:'CTI'});
if (!recommendations.length)
  recommendations.push({priority:'P3', action:'Manter monitoramento contínuo e validar mudanças relevantes na próxima janela.', owner:'CTI'});
if (qualityIssues.length)
  recommendations.push({priority:'P2', action:'Tratar alertas de qualidade para evitar conclusões baseadas em amostra incompleta.', owner:'CTI Engineering'});

const executive = {
  riskScore: score,
  riskLevel: level,
  analyticalConfidence: confidence,
  decision: level === 'CRÍTICO' ? 'Escalonamento imediato' :
    level === 'ALTO' ? 'Ação prioritária no mesmo ciclo operacional' :
    level === 'MODERADO' ? 'Triagem e acompanhamento dirigido' : 'Monitoramento de rotina',
  topSignals: [
    `${stats.ransomwareVictims || 0} vítima(s) de ransomware`,
    `${stats.kevAdded || 0} nova(s) KEV`,
    `${sev.CRITICAL || 0} CVE(s) crítica(s)`,
    `${stats.brVictims || 0} vítima(s) no Brasil`,
  ],
};
const dataQuality = {
  status: qualityIssues.length ? 'ATENÇÃO' : 'OK',
  issues: qualityIssues,
  checksPerformed: 6,
  completenessNote: qualityIssues.length ? 'Há ressalvas que devem acompanhar a interpretação.' : 'Sem ressalvas automáticas detectadas.',
};
const appendix = [
  '', '================================================================================',
  '4. AVALIAÇÃO EXECUTIVA DE RISCO',
  '================================================================================', '',
  `Score: ${score}/100 | Nível: ${level} | Confiança analítica: ${confidence}`,
  `Decisão recomendada: ${executive.decision}`, '',
  'Ações recomendadas:',
  ...recommendations.map(r => `- [${r.priority}] ${r.action} Responsável: ${r.owner}`),
  '', `Qualidade dos dados: ${dataQuality.status} — ${dataQuality.completenessNote}`,
  ...qualityIssues.map(i => '- Ressalva: ' + i),
].join('\n');
return [{ json: {
  ...src,
  reportText: String(src.reportText || '') + appendix,
  stats: {...stats, riskAssessment: executive, recommendations, dataQuality},
  executive,
  dataQuality,
  recommendations,
} }];

